                                <h2 id="-POSTapi-v1-admin-skills--id--audit">审核技能</h2>

<p>
<small class="badge badge-darkred">requires authentication</small>
</p>

<p>管理员审核待审核技能，通过后状态变更为 published，拒绝后变更为 rejected。仅管理员可调用。</p>

<span id="example-requests-POSTapi-v1-admin-skills--id--audit">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "https://xiaoxia.ren/api/v1/admin/skills/1/audit" \
    --header "Authorization: Bearer {SANCTUM_TOKEN}" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"approve\": true,
    \"note\": \"内容合规\"
}"
</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "https://xiaoxia.ren/api/v1/admin/skills/1/audit"
);

const headers = {
    "Authorization": "Bearer {SANCTUM_TOKEN}",
    "Content-Type": "application/json",
    "Accept": "application/json",
};

let body = {
    "approve": true,
    "note": "内容合规"
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

